code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    wall = next(c for c in range(w) if any(row[c] == 4 for row in grid))
    rules = {
        ((1, 1, 0), (1, 0, 1), (0, 1, 0)): ("R", 3),
        ((1, 0, 1), (1, 0, 1), (1, 1, 1)): ("L", 2),
        ((1, 0, 1), (0, 1, 0), (0, 1, 0)): ("D", 2),
        ((1, 1, 1), (0, 1, 0), (1, 0, 1)): ("L", 4),
        ((0, 1, 0), (0, 1, 0), (0, 1, 0)): ("D", 2),
    }
    objects = []
    for c in (0, 4):
        for r in range(0, h - 2, 4):
            color = next((grid[i][j] for i in range(r, r + 3)
                          for j in range(c, c + 3) if grid[i][j] not in (0, 4, 5)), 0)
            if color:
                shape = tuple(tuple(int(grid[i][j] == color)
                                    for j in range(c, c + 3))
                              for i in range(r, r + 3))
                objects.append((shape, color))

    out = [[0] * (wall - 1) for _ in range(h)]
    marker_col = next(c for row in grid for c, value in enumerate(row) if value == 5) - wall - 1
    out[0][marker_col] = 5
    y, x = 0, marker_col
    for shape, color in objects:
        direction, length = rules[shape]
        if direction == "D":
            for yy in range(y + 1, y + length + 1):
                out[yy][x] = color
            y += length
        else:
            y += 1
            step = 1 if direction == "R" else -1
            for xx in range(x, x + step * length, step):
                out[y][xx] = color
            x += step * (length - 1)
    return out
'''
